/bin/bash -lc "python3 << 'EOF'
from PIL import Image
import numpy as np
a = np.array(Image.open('first_frame.png'))
h, w, _ = a.shape
R, G, B = a[...,0].astype(int), a[...,1].astype(int), a[...,2].astype(int)

# coarse 64x36 ascii map (each cell 4x4 px)
chars = {}
for cy in range(36):
    line = \"\"
    for cx in range(64):
        block = a[cy*4:(cy+1)*4, cx*4:(cx+1)*4]
        r, g, b = block[...,0].mean(), block[...,1].mean(), block[...,2].mean()
        if r > 150 and 60 < g < 170 and b < 90:
            c = 'O'   # orange
        elif b > 150 and b > r + 20 and g > 140:
            c = 'B'   # light blue
        elif r > 200 and g > 200 and b > 200:
            c = 'W'   # white
        elif r < 60 and g < 60 and b < 60:
            c = '#'   # dark
        elif r > 100 and g > 100 and b > 100 and abs(r-g) < 25 and abs(g-b) < 25:
            c = '.'   # gray
        else:
            c = '?'
        line += c
    print(line)
EOF"
